<?php
require_once __DIR__.'/../common/config.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=$_POST['action'];try{$pdo->beginTransaction();$s=$pdo->prepare("SELECT w.*,u.username,u.upi_id FROM withdrawals w JOIN users u ON u.id=w.user_id WHERE w.id=? FOR UPDATE");$s->execute([$id]);$w=$s->fetch();if(!$w||$w['status']!=='Pending')throw new RuntimeException('Request is no longer pending.');if($action==='approve'){$pdo->prepare("UPDATE withdrawals SET status='Completed' WHERE id=?")->execute([$id]);$pdo->prepare("UPDATE users SET wallet_balance=wallet_balance-? WHERE id=? AND wallet_balance>=?")->execute([$w['amount'],$w['user_id'],$w['amount']]);$pdo->prepare("INSERT INTO transactions(user_id,amount,type,description) VALUES(?,?, 'debit',?)")->execute([$w['user_id'],$w['amount'],'Withdrawal completed to '.$w['upi_id']]);}else{$pdo->prepare("UPDATE withdrawals SET status='Rejected' WHERE id=?")->execute([$id]);}$pdo->commit();flash('success','Withdrawal request updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}redirect('withdrawal_requests.php');}
$rows=$pdo->query("SELECT w.*,u.username,u.email,u.upi_id FROM withdrawals w JOIN users u ON u.id=w.user_id ORDER BY w.created_at DESC")->fetchAll();$pageTitle='Withdrawal Requests';require __DIR__.'/common/header.php';
?>
<h1 class="text-2xl font-black mb-5">Withdrawal Requests</h1><div class="space-y-3"><?php foreach($rows as $r):?><div class="card rounded-2xl p-4"><div class="flex flex-wrap justify-between"><div><b><?=e($r['username'])?></b> · <?=money($r['amount'])?><div class="text-sm text-slate-400">UPI: <?=e($r['upi_id']?:'Not set')?></div></div><span><?=e($r['status'])?></span></div><?php if($r['status']==='Pending'):?><form method="post" class="flex gap-2 mt-4"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="approve" class="bg-emerald-600 rounded-xl px-4 py-2">Approve</button><button name="action" value="reject" class="bg-rose-600 rounded-xl px-4 py-2">Reject</button></form><?php endif;?></div><?php endforeach;?></div>
<?php require __DIR__.'/common/bottom.php'; ?>
